```ts
export function recite(startVerse: number, endVerse: number): string {
  const days = [
    "first", "second", "third", "fourth", "fifth", "sixth",
    "seventh", "eighth", "ninth", "tenth", "eleventh", "twelfth"
  ];

  const gifts = [
    "a Partridge in a Pear Tree",
    "two Turtle Doves",
    "three French Hens",
    "four Calling Birds",
    "five Gold Rings",
    "six Geese-a-Laying",
    "seven Swans-a-Swimming",
    "eight Maids-a-Milking",
    "nine Ladies Dancing",
    "ten Lords-a-Leaping",
    "eleven Pipers Piping",
    "twelve Drummers Drumming"
  ];

  function verse(n: number): string {
    const day = days[n - 1];
    const dayNumber = n.toString();
    const verseGifts = gifts.slice(0, n).reverse().join(", ");
    const conjunction = n > 1 ? ", and " : "";
    return `On the ${day} day of Christmas my true love gave to me: ${verseGifts}${conjunction}.\n`;
  }

  let result = "";
  for (let i = startVerse; i <= endVerse; i++) {
    result += verse(i);
  }
  return result;
}
